import { createHmac } from "node:crypto";
import { describe, expect, it } from "vitest";
import { verifyToken } from "../src/auth/jwt";

const SECRET = "test-secret";
const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (header: object, payload: object, secret = SECRET) => {
  const data = `${b64(header)}.${b64(payload)}`;
  return `${data}.${createHmac("sha256", secret).update(data).digest("base64url")}`;
};
const future = () => Math.floor(Date.now() / 1000) + 3600;

describe("verifyToken", () => {
  it("accepts a valid token and returns its claims", () => {
    const exp = future();
    expect(verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp }), SECRET)).toEqual({ sub: "u1", exp });
  });

  it("rejects tokens signed with a different secret", () => {
    expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: future() }, "other"), SECRET)).toThrow();
  });

  it("rejects tampered payloads", () => {
    const [h, , s] = sign({ alg: "HS256" }, { sub: "u1", exp: future() }).split(".");
    expect(() => verifyToken(`${h}.${b64({ sub: "admin", exp: future() })}.${s}`, SECRET)).toThrow();
  });

  it("rejects unsigned alg=none tokens", () => {
    expect(() => verifyToken(`${b64({ alg: "none" })}.${b64({ sub: "admin", exp: future() })}.`, SECRET)).toThrow();
  });

  it("rejects expired tokens", () => {
    const exp = Math.floor(Date.now() / 1000) - 1;
    expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp }), SECRET)).toThrow(/expired/);
  });

  it("rejects tokens missing exp", () => {
    expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1" }), SECRET)).toThrow();
  });
});

